sp_widget.client_script:
api.controller = function($scope) {

    var c = this;

    c.scanning = false;
    c.message = '';
    c.success = '';
    c.error = '';

    var video = null;
    var stream = null;
    var scanInterval = null;

    c.startScanner = function() {

        c.message = 'Starting camera...';
        c.error = '';
        c.success = '';

        video = document.getElementById('qrVideo');

        if (!navigator.mediaDevices ||
            !navigator.mediaDevices.getUserMedia) {

            c.error = 'Camera access is not supported on this device.';
            return;
        }

        navigator.mediaDevices.getUserMedia({
            video: {
                facingMode: {
                    ideal: 'environment'
                }
            }
        }).then(function(cameraStream) {

            stream = cameraStream;
            video.srcObject = stream;

            c.scanning = true;
            c.message = 'Point your camera at the interview QR code.';

            $scope.$applyAsync();

            startQRDetection();

        }).catch(function(error) {

            c.error =
                'Camera permission denied or camera unavailable.';

            c.scanning = false;

            $scope.$applyAsync();
        });
    };


    function startQRDetection() {

        if (!('BarcodeDetector' in window)) {

            c.error =
                'QR scanning is not supported by this browser. Please use Chrome.';

            $scope.$applyAsync();

            return;
        }

        var detector = new BarcodeDetector({
            formats: ['qr_code']
        });

        scanInterval = setInterval(function() {

            if (!video ||
                video.readyState !== video.HAVE_ENOUGH_DATA) {
                return;
            }

            detector.detect(video)
                .then(function(barcodes) {

                    if (!barcodes.length) {
                        return;
                    }

                    var qrValue = barcodes[0].rawValue;

                    processQRCode(qrValue);

                })
                .catch(function() {
                    // Ignore individual scan errors
                });

        }, 500);
    }


    function processQRCode(qrValue) {

        stopScanner();

        c.message = 'QR code detected. Validating...';

        $scope.$applyAsync();

        if (!qrValue) {

            c.error = 'Invalid QR code.';
            $scope.$applyAsync();

            return;
        }

        var parts = qrValue.split('|');

        if (parts.length !== 2 ||
            parts[0] !== 'CAMPUS360') {

            c.error =
                'Invalid Campus360 QR code.';

            $scope.$applyAsync();

            return;
        }

        var interviewId = parts[1];

        c.server.get({
            action: 'mark_present',
            interview_id: interviewId
        }).then(function(response) {

            if (response.data.success) {

                c.success =
                    'Attendance marked successfully!';

                c.message =
                    response.data.message || '';

            } else {

                c.error =
                    response.data.error ||
                    'Unable to mark attendance.';
            }

            $scope.$applyAsync();

        });
    }


    function stopScanner() {

        if (scanInterval) {

            clearInterval(scanInterval);
            scanInterval = null;
        }

        if (stream) {

            stream.getTracks().forEach(function(track) {
                track.stop();
            });

            stream = null;
        }

        if (video) {
            video.srcObject = null;
        }

        c.scanning = false;
    }


    c.stopScanner = function() {

        stopScanner();

        c.message = '';
        $scope.$applyAsync();
    };

};

sp_widget.css:
.campus-scanner {
    max-width: 500px;
    margin: 30px auto;
    padding: 30px;
    text-align: center;
    background: #ffffff;
    border-radius: 12px;
    box-shadow: 0 3px 15px rgba(0,0,0,0.12);
}

.campus-scanner h2 {
    margin-bottom: 10px;
}

.instruction {
    color: #666;
    margin-bottom: 20px;
}

.scanner-box {
    position: relative;
    width: 100%;
    max-width: 400px;
    margin: 20px auto;
    overflow: hidden;
    border-radius: 10px;
    background: #000;
}

.scanner-box video {
    width: 100%;
    display: block;
}

.scan-line {
    position: absolute;
    left: 10%;
    right: 10%;
    top: 50%;
    height: 2px;
    background: red;
}

.campus-scanner button {
    margin: 10px;
}

sp_widget.script:
(function() {

    data.success = false;
    data.error = '';
    data.message = '';

    if (!input || input.action != 'mark_present') {
        return;
    }

    if (!input.interview_id) {

        data.error = 'Interview ID is missing.';
        return;
    }

    var gr = new GlideRecord('x_snc_campus360_mock_interview');

    if (!gr.get(input.interview_id)) {

        data.error = 'Interview record not found.';
        return;
    }

    // Already marked
    if (gr.getValue('attendance_status') == 'Present') {

        data.success = true;
        data.message = 'Attendance was already marked as Present.';
        return;
    }

    // Mark attendance
    gr.setValue('attendance_status', 'Present');
    gr.setValue('qr_status', 'Scanned');

    gr.update();

    data.success = true;
    data.message = 'Attendance marked successfully for ' +
                   gr.getValue('interview_id');

})();
